#include <bits/stdc++.h>
using namespace std;

long long power(long long base, int exp, int mod) {
    long long result = 1;
    long long b = base % mod;
    for (int i = 0; i < 64; i++) {
        if (((exp >> i) & 1) == 1) result = result * b % mod;
        b = b * b % mod;
    }
    return result;
}

long long combination(int n, int r, int mod, vector<vector<long long>>& factInv) {
    if (n < 0 || r < 0 || r > n) return 0;
    return factInv[0][n] * factInv[1][r] % mod * factInv[1][n - r] % mod;
}

vector<vector<long long>> generateFactorials(int n, int mod) {
    vector<long long> fact(n + 1);
    vector<long long> invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % mod;
    }
    long long invNFact = power(fact[n], mod - 2, mod);
    invFact[n] = invNFact;
    for (int i = n - 1; i >= 0; i--) {
        invFact[i] = invFact[i + 1] * (i + 1) % mod;
    }
    return {fact, invFact};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int mod = 998244353;
    int n;
    long long K;
    cin >> n >> K;
    if (K >= n) {
        cout << 0 << "\n";
        return 0;
    }
    auto factInv = generateFactorials(n + 1, mod);
    if (K == 0) {
        cout << factInv[0][n] << "\n";
        return 0;
    }
    long long answer = 0;
    for (int i = n - (int)K; i >= 1; i--) {
        int sign = (((n - (int)K - i) % 2) == 0) ? 1 : -1;
        long long term = combination(n, i, mod, factInv) * power(i, n, mod) % mod;
        term = term * sign % mod;
        term = term * combination(n - i, (int)K, mod, factInv) % mod;
        answer = (answer + term) % mod;
    }
    answer = (answer * 2) % mod;
    cout << answer << "\n";
    return 0;
}

